module jelly_raid (input clk, input rst_n, input start, input [2:0] start_row, start_col, input [2:0] target_row, target_col, input [7:0] map_data [0:7][0:7], input [2:0] m1_path [0:3], input [2:0] m2_path [0:3], output reg [7:0] min_turns, output reg possible); reg [1:0] state; reg [7:0] current_turn; reg [63:0] reachable_set; reg [7:0] min_turns; reg possible; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 2'b00; current_turn <=8'd0; reachable_set <=64'd0; min_turns <=8'd0; possible <=0; end else begin if (state == 2'b00) begin if (start) begin state <= 2'b01; current_turn <=8'd0; min_turns <=8'd0; possible <=0; end end end end endmodule